import numpy as np, cv2
z=np.load('source_pixels.npz')['rgb']
cats=[('red',[(0,12),(170,180)]),('orange',[(12,25)]),('yellow',[(25,38)]),('green',[(38,85)]),('cyan',[(85,98)]),('blue',[(98,132)]),('purple',[(132,160)]),('pink',[(160,170)])]
for fi in [0,12,24,48,95]:
 im=z[fi]; hsv=cv2.cvtColor(im,cv2.COLOR_RGB2HSV)
 print('\\nFRAME',fi)
 for name,ranges in cats:
  m=np.zeros(im.shape[:2],bool)
  for lo,hi in ranges: m|=(hsv[:,:,0]>=lo)&(hsv[:,:,0]<hi)
  m &= (hsv[:,:,1]>=70)&(hsv[:,:,2]>=40)
  n,lab,stats,cent=cv2.connectedComponentsWithStats(m.astype('uint8'),8)
  comps=[]
  for j in range(1,n):
   x,y,w,h,area=stats[j]
   if area>=12: comps.append((int(area),(int(x),int(y),int(w),int(h)),tuple(np.round(cent[j],1))))
  if comps: print(name,sorted(comps,reverse=True)[:6])
PY"
